#!/usr/bin/env python3
import os
from PIL import Image, ImageDraw, ImageFont

def create_icon():
    # Crear una imagen de 256x256
    size = 256
    img = Image.new('RGBA', (size, size), (79, 70, 229, 255))  # Color azul
    draw = ImageDraw.Draw(img)
    
    # Dibujar un borde redondeado
    corner_radius = 32
    draw.rounded_rectangle(
        [0, 0, size, size], 
        radius=corner_radius, 
        fill=(79, 70, 229, 255),
        outline=(124, 58, 237, 255), 
        width=4
    )
    
    # Intentar cargar una fuente, si no existe usar la por defecto
    try:
        font = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", 80)
    except:
        try:
            font = ImageFont.load_default()
        except:
            font = None
    
    # Dibujar el texto "FA"
    text = "FA"
    if font:
        bbox = draw.textbbox((0, 0), text, font=font)
        text_width = bbox[2] - bbox[0]
        text_height = bbox[3] - bbox[1]
    else:
        text_width = 60
        text_height = 60
    
    x = (size - text_width) // 2
    y = (size - text_height) // 2 - 10
    
    draw.text((x, y), text, fill=(255, 255, 255, 255), font=font)
    
    # Dibujar algunos elementos decorativos (píldoras)
    draw.ellipse([80-12, 180-12, 80+12, 180+12], fill=(255, 255, 255, 200))
    draw.ellipse([176-12, 180-12, 176+12, 180+12], fill=(255, 255, 255, 200))
    
    # Dibujar una línea decorativa
    draw.rounded_rectangle([68, 200, 188, 208], radius=4, fill=(255, 255, 255, 150))
    
    return img

if __name__ == "__main__":
    try:
        icon = create_icon()
        icon.save("assets/icon.png", "PNG")
        print("✓ Ícono PNG creado exitosamente")
        
        # Crear versiones en diferentes tamaños
        for size in [16, 32, 48, 64, 128, 256]:
            resized = icon.resize((size, size), Image.Resampling.LANCZOS)
            resized.save(f"assets/icon_{size}.png", "PNG")
        
        print("✓ Íconos en múltiples tamaños creados")
            
    except ImportError:
        print("⚠ PIL no está instalado. Creando ícono básico...")
        # Crear un ícono muy básico sin PIL
        import base64
        
        # Crear un PNG básico de 256x256 (datos base64 de un PNG simple)
        png_data = base64.b64decode("""
""")
        with open("assets/icon.png", "wb") as f:
            f.write(png_data)
        print("✓ Ícono básico creado")
    except Exception as e:
        print(f"✗ Error: {e}")
